  VALUES (v_pod_id, 'الانفصال فى العلاقات|كيف ترجعي قوية | بودكاست وعي|', 'رابط الحلقة على اليوتيوب ❤️ https://youtu.be/W8gmaPC-Br8?si=c0RYgShXWGP_UoP1 قناة بودكاست وعي @wahe4 تابعيني✨ في الفيديو ده هنتكلم عن: • سبب تعلقك بالاشخاص فى حياتك؟ • كيف تتخلصي من التعلق بخطوات عملية؟ • أمثلة يومية هتساعدك تكوني قوية و تتخلصي من التعلق • علامات التلاعب العاطفي وإزاي تواجهيها بحكمة. 💡 الفيديو مليان أمثلة حقيقية وحوارات عملية تقدري تطبقيها في حياتك اليومية عشان تقوي علاقتك وتزودي قيمتك عند شريكك. #علاقات #التعلق #relationship ⸻ ❓ سؤال للنقاش: 1. هل حسّيتي إنك في علاقة تعلق قبل كده؟ 2. أي سبب من الأسباب اللي قلتها حسّيتي إنه أكتر سبب ليكي؟ 3. إيه أول خطوة هتعمليها عشان تتحرري ', 'https://anchor.fm/s/108148058/podcast/play/109113913/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-9-2%2F408533801-44100-2-62d1551839eef.mp3', 1529, '2025-10-02 12:17:32'::timestamptz, 23000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'تخلصي من التعلق| بودكاست وعي', 'كيف تتخلصي من التعلق | بودكاست وعي هل عمرك حسيتِ إن حياتك واقفة على وجود شخص واحد؟ هل بتشيكي موبايلك كل دقيقة مستنية رسالة منه؟ هل ساعات بتلغِي نفسك وهواياتك وأصحابك عشان بس تفضلي معاه؟ ❤️للمتابعة على يوتيوب قناة بودكاست وعي ابحثى عن @wahe4 رابط القناة https://www.youtube.com/@Wahe4 🎥 في الفيديو ده هنجاوب على أسئلة مهمة جدًا لكل بنت: • إيه الفرق بين الحب والتعلّق؟ • إزاي تعرفي إنك متعلقة زيادة ومش بتحبي حب صحي؟ • إيه الجذور اللي بتخليكي تتعلقي بسرعة؟ • إيه العلامات اللي بتكشف إنك سجينة التعلّق؟ • إزاي تقدري ترجعي لنفسك وتتحرري من أي علاقة بتستهلكك؟ • إيه الخطوات العملية اللي لازم تعمليها عشان', 'https://anchor.fm/s/108148058/podcast/play/109113586/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-9-2%2F408533065-44100-2-ebbb7eb414c69.mp3', 1576, '2025-10-02 11:40:51'::timestamptz, 24000);
