  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'حب الذات', 'سلسة حب الذات الحلقة ١ كيف تحب الذات وما يؤثر على حبك لذاتك كيف تزيد ثقتك بنفسك و تنجح فى حياتك حب الذات تقبل الذات تطوير الذات الثقة بالنفس التحكم فى المشاعر تنظيم المشاعر وعي كيف افهم ذاتي كيف تزيد ثقتك بنفسك احترام الذات الراحة النفسية تقدير النفس السلام الداخلي التخلص من جلد الذات تنمية شخصية كيف أتصالح مع نفسي خطوات حب النفس الصحة النفسية كيف تحب نفسك الوعي الذاتي النمو الذاتي كيف أحب نفسي حب النفس كيف أطور ذاتي التصالح مع الذات التحفيز الذاتي التخلص من القلق التفكير الإيجابي عيش بسلام توازن نفسي قوة العقل السلام مع الذات حب الذات أولاً الشفاء الداخلي قوة حب النفس بناء الثقة بالنفس اكتشاف', 'https://anchor.fm/s/108148058/podcast/play/106568363/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-7%2F405279775-44100-2-df59253e032b1.mp3', 1539, '2025-08-07 14:33:43'::timestamptz, 33000);
